            ["Place the object on the highlighted spaces:\n"] = new[] { "Coloquen el elemento en las casillas resaltadas:\n", "Placez l'élément sur les cases en surbrillance :\n", "Stellt das Objekt auf die hervorgehobenen Felder:\n", "Posizionate l'elemento sulle caselle evidenziate:\n", "Postawcie obiekt na podświetlonych polach:\n", "Helyezzétek az objektumot a kiemelt mezőkre:\n", "将物件放置在高亮的格子上：\n", "Položte objekt na zvýrazněná pole:\n", "강조 표시된 칸에 오브젝트를 놓으세요:\n", "Поставьте объект на подсвеченные клетки:\n", "將物件放在標示的格子上：\n" },
            ["Place the objects on the highlighted spaces:\n"] = new[] { "Coloquen los elementos en las casillas resaltadas:\n", "Placez les éléments sur les cases en surbrillance :\n", "Stellt die Objekte auf die hervorgehobenen Felder:\n", "Posizionate gli elementi sulle caselle evidenziate:\n", "Postawcie obiekty na podświetlonych polach:\n", "Helyezzétek az objektumokat a kiemelt mezőkre:\n", "将这些物件放置在高亮的格子上：\n", "Položte objekty na zvýrazněná pole:\n", "강조 표시된 칸에 오브젝트들을 놓으세요:\n", "Поставьте объекты на подсвеченные клетки:\n", "將這些物件放在標示的格子上：\n" },
            ["And also:\n"] = new[] { "Y también:\n", "Et aussi :\n", "Und außerdem:\n", "E inoltre:\n", "A także:\n", "És még:\n", "以及：\n", "A také:\n", "그리고:\n", "А также:\n", "還有：\n" },
            ["Objects"] = new[] { "Elementos", "Éléments", "Objekte", "Elementi", "Obiekty", "Objektumok", "物件", "Objekty", "오브젝트", "Объекты", "物件" },
            ["<b>Point of interest.</b> To explore, choose a hero (tap their portrait) and tap here. Exploring does not use the hero's action; the hero must be adjacent to the token (diagonals count) or in the same space."] = new[] { "<b>Punto de interés.</b> Para explorar, elijan un héroe (toquen su retrato) y toquen aquí. Explorar no gasta la acción del héroe; el héroe debe estar adyacente al marcador (las diagonales cuentan) o en la misma casilla.", "<b>Point d'intérêt.</b> Pour explorer, choisissez un héros (touchez son portrait) puis touchez ici. Explorer ne consomme pas l'action du héros ; le héros doit être adjacent au jeton (les diagonales comptent) ou sur la même case.", "<b>Interessanter Ort.</b> Zum Erkunden wählt einen Helden (tippt auf sein Porträt) und tippt hier. Erkunden verbraucht nicht die Aktion des Helden; der Held muss an den Marker angrenzen (diagonal zählt) oder auf demselben Feld stehen.", "<b>Punto di interesse.</b> Per esplorare, scegliete un eroe (toccate il suo ritratto) e toccate qui. Esplorare non consuma l'azione dell'eroe; l'eroe deve essere adiacente al segnalino (le diagonali contano) o nella stessa casella.", "<b>Punkt zainteresowania.</b> Aby eksplorować, wybierzcie bohatera (dotknijcie jego portretu) i dotknijcie tutaj. Eksploracja nie zużywa akcji bohatera; bohater musi sąsiadować z żetonem (po przekątnej też się liczy) lub stać na tym samym polu.", "<b>Érdekes hely.</b> A felfedezéshez válasszatok egy hőst (koppintsatok a portréjára), majd koppintsatok ide. A felfedezés nem használja el a hős akcióját; a hősnek a jelzővel szomszédos mezőn (az átló is számít) vagy ugyanazon a mezőn kell állnia.", "<b>兴趣点。</b>要进行探索，请选择一位英雄（点击其头像），然后点击此处。探索不消耗英雄的行动；英雄必须与该标记相邻（斜向也算）或位于同一格。", "<b>Zajímavé místo.</b> Pro průzkum vyberte hrdinu (klepněte na jeho portrét) a klepněte sem. Průzkum nespotřebuje akci hrdiny; hrdina musí sousedit se žetonem (úhlopříčně se počítá) nebo stát na stejném poli.", "<b>관심 지점.</b> 탐험하려면 영웅을 선택하고(초상화를 누르세요) 여기를 누르세요. 탐험은 영웅의 행동을 소모하지 않습니다. 영웅은 토큰에 인접(대각선 포함)하거나 같은 칸에 있어야 합니다.", "<b>Точка интереса.</b> Чтобы исследовать, выберите героя (нажмите на его портрет) и нажмите сюда. Исследование не тратит действие героя; герой должен находиться рядом с жетоном (по диагонали тоже считается) или в той же клетке.", "<b>興趣點。</b>要進行探索，請選擇一位英雄（點選其頭像），然後點選此處。探索不會消耗英雄的行動；英雄必須與該標記相鄰（斜向也算）或位於同一格。" },
            ["To use it, choose a hero and spend one of their actions on this object."] = new[] { "Para usarlo, elijan un héroe y gasten una de sus acciones en este elemento.", "Pour l'utiliser, choisissez un héros et dépensez l'une de ses actions sur cet élément.", "Um es zu benutzen, wählt einen Helden und gebt eine seiner Aktionen für dieses Objekt aus.", "Per usarlo, scegliete un eroe e spendete una delle sue azioni su questo elemento.", "Aby go użyć, wybierzcie bohatera i wydajcie jedną z jego akcji na ten obiekt.", "A használathoz válasszatok egy hőst, és költsétek el egy akcióját erre az objektumra.", "要使用它，请选择一位英雄，并在此物件上花费该英雄的一个行动。", "Pro použití vyberte hrdinu a utraťte jednu z jeho akcí na tento objekt.", "사용하려면 영웅을 선택하고 그 영웅의 행동 하나를 이 오브젝트에 사용하세요.", "Чтобы использовать, выберите героя и потратьте одно его действие на этот объект.", "要使用它，請選擇一位英雄，並在此物件上花費該英雄的一個行動。" },
            ["<i>(Already used: tapping here does not use the hero's action.)</i>"] = new[] { "<i>(Ya usado: tocar aquí no gasta la acción del héroe.)</i>", "<i>(Déjà utilisé : toucher ici ne consomme pas l'action du héros.)</i>", "<i>(Bereits benutzt: Hier zu tippen verbraucht nicht die Aktion des Helden.)</i>", "<i>(Già usato: toccare qui non consuma l'azione dell'eroe.)</i>", "<i>(Już użyty: dotknięcie tutaj nie zużywa akcji bohatera.)</i>", "<i>(Már használva: ide koppintva nem használjátok el a hős akcióját.)</i>", "<i>(已使用：点击此处不会消耗英雄的行动。)</i>", "<i>(Již použito: klepnutí sem nespotřebuje akci hrdiny.)</i>", "<i>(이미 사용함: 여기를 눌러도 영웅의 행동을 소모하지 않습니다.)</i>", "<i>(Уже использовано: нажатие здесь не тратит действие героя.)</i>", "<i>(已使用：點選此處不會消耗英雄的行動。)</i>" },
            ["Custom tile"] = new[] { "Loseta personalizada", "Tuile personnalisée", "Eigenes Spielplanteil", "Tessera personalizzata", "Własny kafel", "Egyedi lapka", "自定义板块", "Vlastní dílek", "사용자 타일", "Свой тайл", "自訂板塊" },
            ["Defeat. The heroes fall back, wounded, and the map is lost."] = new[] { "Derrota. Los héroes se retiran, heridos, y el mapa se pierde.", "Défaite. Les héros battent en retraite, blessés, et la carte est perdue.", "Niederlage. Die Helden ziehen sich verwundet zurück, und die Karte ist verloren.", "Sconfitta. Gli eroi ripiegano, feriti, e la mappa è persa.", "Porażka. Bohaterowie wycofują się ranni, a mapa jest stracona.", "Vereség. A hősök sebesülten visszavonulnak, és a térkép elveszett.", "失败。英雄们负伤撤退，此地图宣告失败。", "Porážka. Hrdinové ustupují zranění a mapa je ztracena.", "패배. 영웅들이 부상을 입고 후퇴합니다. 이 맵은 실패했습니다.", "Поражение. Раненые герои отступают, и карта проиграна.", "失敗。英雄們負傷撤退，這張地圖宣告失敗。" },
            ["Victory! The map is complete."] = new[] { "¡Victoria! El mapa está completado.", "Victoire ! La carte est terminée.", "Sieg! Die Karte ist abgeschlossen.", "Vittoria! La mappa è completata.", "Zwycięstwo! Mapa ukończona.", "Győzelem! A térkép teljesítve.", "胜利！地图已完成。", "Vítězství! Mapa je dokončena.", "승리! 맵을 완료했습니다.", "Победа! Карта пройдена.", "勝利！地圖已完成。" },
