            ["Place the tiles:\n"] = new[] { "Coloquen las losetas:\n", "Placez les tuiles :\n", "Legt die Spielplanteile aus:\n", "Posizionate le tessere:\n", "Połóżcie kafle:\n", "Helyezzétek le a lapkákat:\n", "放置这些板块：\n", "Položte dílky:\n", "타일들을 놓으세요:\n", "Положите тайлы:\n", "放置這些板塊：\n" },
